"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6310],{6310:a=>{a.exports=JSON.parse('{"slug":"vvod-izhs-2026-upal-na-21-procent-eskrou","locale":"zh","title":"前9个月独栋住宅竣工下降21%，为2021年以来最低","description":"2026年一月至九月独栋竣工少21%至41.4百万平方米。托管账户与昂贵贷款如何改变建房市场。","blocks":[{"id":"b001","kind":"paragraph","text":"2026年前9个月俄罗斯住宅交付66.3百万平方米，同比少13.4%。下跌全来自独栋：41.4百万，少21%，上次更低是2021年35.1百万。公寓楼反增3%至24.9百万。独栋占比一年降5.9个百分点至62.5%。"},{"id":"b002","kind":"paragraph","text":"5大建设地区中，莫斯科州和库班下跌最重。莫斯科州前9个月6.9百万平方米，少29.5%；克拉斯诺达尔3.1百万，少31.7%。CIAN分析师叶莲娜\xb7博布罗夫斯卡娅归因贵贷款及经济停滞；独栋还叠加转托管账户及“乡村住宅登记特赦”效应消退。Starkwood的阿斯塔菲耶夫估项目预算一年涨10–15%，快于通胀。"},{"id":"b003","kind":"paragraph","text":"设想客户把钱存银行，裁缝需成衣试穿后才拿钱，布料、线和助手工资先自付或借。大型店能承受，小作坊难，这就是托管。自2025年三月1日，优惠房贷独栋承包商只能这样收款：房屋登记后5个工作日内。目前约1.5千家承包商使用此机制。"},{"id":"b004","kind":"paragraph","text":"第二因素是统计：独栋竣工按登记计算，长期由登记旧房的特赦抬高，贡献25–30%。简化登记已延至2031年，但M9 Development运营主管安东\xb7米内江认为效应接近耗尽。部分下降并非少建，而是旧房已登记完。"},{"id":"b005","kind":"paragraph","text":"九月独栋交付2026年首次同比增4%至5.3百万平方米；同期独栋房贷比八月增42%至近17千笔。家庭赶十月1日前签约，因为一个孩子家庭利率将从6%升至10–12%。若贷款用于新建，交付影响会稍后出现。"},{"id":"b006","kind":"paragraph","text":"建设部预计2026全年住宅87.7百万平方米，较2025少约20%，郊区少近25%。比前9个月更差，意味着年末跌势加剧。想用优惠房贷建房者只能选经银行审批的承包商，而预算涨得比物价快。大开发商可替代小队伍，但社区在首批销售前就需道路和管网。"},{"id":"b007","kind":"heading","text":"2026年独栋交付下降多少？"},{"id":"b008","kind":"paragraph","text":"2026年一月至九月41.4百万平方米，少21%；仅2021年更低，为35.1百万。全部住宅少13%至66.3百万平方米。"},{"id":"b009","kind":"heading","text":"独栋建设中的托管如何运作？"},{"id":"b010","kind":"paragraph","text":"借款人资金留银行，房屋登记后5个工作日内承包商才收款，施工靠自有或借款。自2025年三月1日，优惠房贷承包建房必须如此。"},{"id":"b011","kind":"heading","text":"独栋交付在恢复吗？"},{"id":"b012","kind":"paragraph","text":"九月同比增4%，为2026首次。但建设部预计全年郊区少近25%，比前9个月更差。十月1日一个孩子家庭房贷升至10–12%，需求可能再降。"}],"sources":[{"label":"独栋交付下降21%","url":"https://www.kommersant.ru/doc/9042244"},{"label":"俄罗斯前三季度住宅交付下降13.4%","url":"https://1prime.ru/20261019/rosstat-874384990.html"},{"label":"九月独栋交付首次在2026超过去年","url":"https://finance.mail.ru/article/v-sentyabre-vvod-izhs-vpervyie-v-2026-m-prevyisil-uroven-proshlogo-goda-69233224/"},{"label":"俄罗斯前三季度住宅交付下降13%","url":"https://realty.ria.ru/20261019/vvod-2125392621.html"},{"label":"186-FZ修订：独栋房贷市场参与者须知","url":"https://harant.ru/blog/bankovskie-voprosy-finansy/izmeneniya-v-186-fz-chto-vazhno-znat-uchastnikam-ipotechnogo-rynka-izhs/"}],"sourceBodySha256":"bcf9ff6044973cdce07fbb0598c5351b940a456fbe7c887a552863309c39870a"}')}}]);